import { Card, CardContent } from '@/components/ui/card'
import { CardHeader } from '@/components/ui/card-header'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { useAppDispatch, useAppSelector } from '@/lib/redux'
import { clearSearch, clearFilters, setSearch, setFilters } from '@/lib/redux/search'
import { useSetRecoilState } from 'recoil'
import { noMatchesStateAtom } from '@/lib/redux/noMatchesState'

export function NoMatchesState({
  onClear,
}: {
  onClear: () => void
}) {
  const dispatch = useAppDispatch()
  const search = useAppSelector((state) => state.search)
  const filters = useAppSelector((state) => state.filters)
  const setRecoilState = useSetRecoilState(noMatchesStateAtom)

  const onClearClick = () => {
    dispatch(clearSearch())
    dispatch(clearFilters())
    setRecoilState({ noMatches: false })
  }

  return (
    <Card>
      <CardHeader>
        <Label>Search</Label>
        <Input
          placeholder="Search"
          aria-label="Search"
          value={search}
          onChange={(e) => dispatch(setSearch(e.target.value))}
        />
      </CardHeader>
      <CardContent>
        <Label>Filters</Label>
        <Input
          placeholder="Filters"
          aria-label="Filters"
          value={filters}
          onChange={(e) => dispatch(setFilters(e.target.value))}
        />
      </CardContent>
      <CardFooter className="flex items-center justify-end gap-1">
        <Button onClick={onClearClick}>Clear</Button>
      </CardFooter>
